const GREEN = 0x22e000;
const BLUE = 0x2878ff;
const CYAN = 0x60f3ef;
const MAGENTA = 0xff76b7;
const WHITE = 0xffffff;

const fixedGroup = new THREE.Group();
const dynamicGroup = new THREE.Group();
scene.add(fixedGroup, dynamicGroup);

const worldUp = new THREE.Vector3(0, 1, 0);
const C1 = new THREE.Vector3(-4.65, -1.65, -0.12);
const P = new THREE.Vector3(0.75, 1.95, 0.56);
const rayDir1 = new THREE.Vector3().subVectors(P, C1).normalize();

function disposeGroup(group) {
  group.traverse(obj => {
    if (obj.geometry) obj.geometry.dispose?.();
    if (obj.material) {
      if (Array.isArray(obj.material)) obj.material.forEach(m => m.dispose?.());
      else obj.material.dispose?.();
    }
  });
  group.clear();
}

function makeBasisFromNormal(n) {
  let u = new THREE.Vector3().crossVectors(worldUp, n);
  if (u.lengthSq() < 1e-7) u = new THREE.Vector3(1, 0, 0).cross(n);
  u.normalize();
  const v = new THREE.Vector3().crossVectors(n, u).normalize();
  return { u, v };
}

function addCylinderBetween(parent, a, b, radius, color, opacity = 1, radial = 18) {
  const dir = new THREE.Vector3().subVectors(b, a);
  const len = dir.length();
  if (len < 1e-6) return null;
  const geom = new THREE.CylinderGeometry(radius, radius, len, radial);
  const mat = new THREE.MeshBasicMaterial({
    color,
    transparent: opacity < 1,
    opacity,
    depthWrite: opacity >= 0.98
  });
  const mesh = new THREE.Mesh(geom, mat);
  mesh.position.copy(a).add(b).multiplyScalar(0.5);
  mesh.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.normalize());
  parent.add(mesh);
  return mesh;
}

function addConeAt(parent, tip, dir, radius, height, color) {
  const d0 = dir.clone().normalize();
  const geom = new THREE.ConeGeometry(radius, height, 28);
  const mat = new THREE.MeshBasicMaterial({ color });
  const cone = new THREE.Mesh(geom, mat);
  cone.position.copy(tip).addScaledVector(d0, -height / 2);
  cone.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), d0);
  parent.add(cone);
  return cone;
}

function addArrow(parent, origin, dir, length, color, radius = 0.022, headScale = 1) {
  const d0 = dir.clone().normalize();
  const headH = Math.min(0.38 * headScale, Math.max(0.15, length * 0.26));
  const shaftEnd = origin.clone().addScaledVector(d0, Math.max(length - headH * 0.72, 0.01));
  const tip = origin.clone().addScaledVector(d0, length);
  addCylinderBetween(parent, origin, shaftEnd, radius, color, 1, 16);
  addConeAt(parent, tip, d0, radius * 5.7 * headScale, headH, color);
  return tip;
}

function addDashedSegment(parent, a, b, color = BLACK, radius = 0.018, dash = 0.25, gap = 0.17) {
  const delta = new THREE.Vector3().subVectors(b, a);
  const len = delta.length();
  if (len < 1e-6) return;
  const dir = delta.clone().normalize();
  for (let t = 0; t < len; t += dash + gap) {
    const t2 = Math.min(t + dash, len);
    addCylinderBetween(
      parent,
      a.clone().addScaledVector(dir, t),
      a.clone().addScaledVector(dir, t2),
      radius,
      color,
      1,
      12
    );
  }
}

function addThickPolyline(parent, points, color = BLACK, radius = 0.026, closed = false) {
  const n = closed ? points.length : points.length - 1;
  for (let i = 0; i < n; i++) {
    addCylinderBetween(parent, points[i], points[(i + 1) % points.length], radius, color, 1, 16);
  }
}

function addPlanePatch(parent, corners, color = WHITE, opacity = 0.16) {
  const geom = new THREE.BufferGeometry().setFromPoints([corners[0], corners[1], corners[2], corners[0], corners[2], corners[3]]);
  geom.setIndex([0, 1, 2, 3, 4, 5]);
  const mat = new THREE.MeshBasicMaterial({
    color,
    transparent: true,
    opacity,
    side: THREE.DoubleSide,
    depthWrite: false
  });
  const mesh = new THREE.Mesh(geom, mat);
  parent.add(mesh);
  return mesh;
}

function addPlaneOutline(parent, center, normal, width, height, color = BLACK, radius = 0.028) {
  const { u, v } = makeBasisFromNormal(normal);
  const corners = [
    center.clone().addScaledVector(u, -width / 2).addScaledVector(v, -height / 2),
    center.clone().addScaledVector(u, width / 2).addScaledVector(v, -height / 2),
    center.clone().addScaledVector(u, width / 2).addScaledVector(v, height / 2),
    center.clone().addScaledVector(u, -width / 2).addScaledVector(v, height / 2)
  ];
  addPlanePatch(parent, corners, WHITE, 0.10);
  addThickPolyline(parent, corners, color, radius, true);
  return { corners, u, v, center, normal: normal.clone(), width, height };
}

function addCamera(parent, center, planeCorners, facingDir, labelSide = 1) {
  const body = new THREE.Mesh(
    new THREE.SphereGeometry(0.22, 40, 20),
    new THREE.MeshBasicMaterial({ color: BLACK })
  );
  body.position.copy(center);
  parent.add(body);

  const aperture = new THREE.Mesh(
    new THREE.SphereGeometry(0.12, 32, 16),
    new THREE.MeshBasicMaterial({ color: 0x000000 })
  );
  aperture.position.copy(center).addScaledVector(facingDir.clone().normalize(), 0.035);
  parent.add(aperture);

  for (const c of planeCorners) addCylinderBetween(parent, center, c, 0.021, BLACK, 1, 14);

  const base = center.clone().add(new THREE.Vector3(0.34 * labelSide, 0.00, -0.06));
  addCylinderBetween(parent, center, base, 0.03, BLACK, 1, 14);
}

function addPoint(parent, pos, fillColor, radius = 0.115, outlineColor = BLACK, outlineScale = 1.38) {
  const halo = new THREE.Mesh(
    new THREE.SphereGeometry(radius * outlineScale, 36, 18),
    new THREE.MeshBasicMaterial({ color: outlineColor })
  );
  halo.position.copy(pos);
  parent.add(halo);

  const dot = new THREE.Mesh(
    new THREE.SphereGeometry(radius, 36, 18),
    new THREE.MeshBasicMaterial({ color: fillColor })
  );
  dot.position.copy(pos);
  parent.add(dot);
  return dot;
}

function projectFromCameraToPlane(cameraCenter, objectPoint, planeCenter, planeNormal) {
  const ray = new THREE.Vector3().subVectors(objectPoint, cameraCenter);
  const denom = planeNormal.dot(ray);
  if (Math.abs(denom) < 1e-7) return planeCenter.clone();
  const t = planeNormal.dot(new THREE.Vector3().subVectors(planeCenter, cameraCenter)) / denom;
  return cameraCenter.clone().addScaledVector(ray, t);
}

function clipLineToPlaneRect(a, b, center, u, v, width, height) {
  const ap = new THREE.Vector3().subVectors(a, center);
  const bp = new THREE.Vector3().subVectors(b, center);
  const ax = ap.dot(u), ay = ap.dot(v);
  const bx = bp.dot(u), by = bp.dot(v);
  const dx = bx - ax, dy = by - ay;
  const hw = width / 2, hh = height / 2;
  const ts = [];

  function addT(t) {
    if (!Number.isFinite(t)) return;
    const x = ax + dx * t;
    const y = ay + dy * t;
    if (x >= -hw - 1e-5 && x <= hw + 1e-5 && y >= -hh - 1e-5 && y <= hh + 1e-5) ts.push(t);
  }

  if (Math.abs(dx) > 1e-9) {
    addT((-hw - ax) / dx);
    addT((hw - ax) / dx);
  }
  if (Math.abs(dy) > 1e-9) {
    addT((-hh - ay) / dy);
    addT((hh - ay) / dy);
  }

  ts.sort((m, n) => m - n);
  const unique = ts.filter((t, i) => i === 0 || Math.abs(t - ts[i - 1]) > 1e-4);
  if (unique.length >= 2) return [a.clone().lerp(b, unique[0]), a.clone().lerp(b, unique[unique.length - 1])];

  const localDir = new THREE.Vector2(dx, dy);
  if (localDir.lengthSq() < 1e-9) {
    return [
      center.clone().addScaledVector(u, -hw),
      center.clone().addScaledVector(u, hw)
    ];
  }
  localDir.normalize();
  const local = new THREE.Vector2(ax, ay);
  const tClosest = -local.dot(localDir);
  const cx = ax + localDir.x * tClosest;
  const cy = ay + localDir.y * tClosest;
  const span = Math.sqrt(hw * hw + hh * hh);
  return [
    center.clone().addScaledVector(u, cx - localDir.x * span).addScaledVector(v, cy - localDir.y * span),
    center.clone().addScaledVector(u, cx + localDir.x * span).addScaledVector(v, cy + localDir.y * span)
  ];
}

function addCurvedArrow(parent, start, control, end, color, radius = 0.032) {
  const curve = new THREE.QuadraticBezierCurve3(start, control, end);
  const tube = new THREE.Mesh(
    new THREE.TubeGeometry(curve, 96, radius, 12, false),
    new THREE.MeshBasicMaterial({ color })
  );
  parent.add(tube);
  addConeAt(parent, end, curve.getTangent(1).normalize(), 0.22, 0.44, color);
}

function setSerif(labelEntry, weight = 'normal') {
  labelEntry.div.style.fontFamily = 'Georgia, Times New Roman, serif';
  labelEntry.div.style.fontWeight = weight;
  return labelEntry;
}

const plane1Normal = rayDir1.clone();
const basis1 = makeBasisFromNormal(plane1Normal);
const p1 = C1.clone().addScaledVector(rayDir1, 2.78);
const plane1Center = p1.clone()
  .addScaledVector(basis1.u, -0.60)
  .addScaledVector(basis1.v, 0.06);

const plane1 = addPlaneOutline(fixedGroup, plane1Center, plane1Normal, 3.05, 3.62, BLACK, 0.029);
addCamera(fixedGroup, C1, plane1.corners, plane1Normal, 1);

const rayEnd = C1.clone().addScaledVector(rayDir1, 8.75);
addCylinderBetween(fixedGroup, C1, rayEnd, 0.052, RED, 1, 24);
addPoint(fixedGroup, p1, RED, 0.115);
addPoint(fixedGroup, P, CYAN, 0.12);

const axisOrigin1 = plane1Center.clone().addScaledVector(plane1Normal, 0.10);
const x1Tip = addArrow(fixedGroup, axisOrigin1, plane1.u.clone().multiplyScalar(-1), 1.13, GREEN, 0.019, 0.92);
const y1Tip = addArrow(fixedGroup, axisOrigin1, plane1.v, 1.16, GREEN, 0.019, 0.92);
const z1Tip = addArrow(fixedGroup, axisOrigin1, plane1Normal, 0.93, GREEN, 0.019, 0.92);

function camera2Center() {
  return new THREE.Vector3(
    4.20 + state.translationCamera2 * 0.18,
    -1.62,
    0.08 + state.translationCamera2 * 0.052
  );
}

function camera2Normal() {
  const base = new THREE.Vector3(-1.66, 0.78, 0.08).normalize();
  return base.applyAxisAngle(worldUp, THREE.MathUtils.degToRad(state.rotationCamera2)).normalize();
}

const labels = {
  camera1: setSerif(addLabel('Camera 1', C1.clone().add(new THREE.Vector3(-0.76, -0.45, -0.03)), { fontSize: '34px', color: '#000' })),
  image1: addLabel('image plane 1', plane1.corners[3].clone().add(new THREE.Vector3(-0.05, 0.23, 0)), { fontSize: '13px', color: '#111', background: 'rgba(255,255,255,0.78)' }),
  p1: setSerif(addLabel('p<sub>1</sub>', p1.clone().add(new THREE.Vector3(-0.28, 0.34, 0.03)), { fontSize: '44px', color: '#000' }), 'bold'),
  P: setSerif(addLabel('P', P.clone().add(new THREE.Vector3(0.02, 0.34, 0.02)), { fontSize: '25px', color: '#000' }), 'bold'),
  ray: addLabel('ray from Camera 1', C1.clone().lerp(P, 0.55).add(new THREE.Vector3(0.10, 0.17, 0.05)), { fontSize: '13px', color: '#d40000', background: 'rgba(255,255,255,0.80)' }),
  axes1: addLabel('coordinate axes 1', axisOrigin1.clone().add(new THREE.Vector3(-0.55, 0.22, 0.02)), { fontSize: '12px', color: '#17c900', background: 'rgba(255,255,255,0.75)' }),
  x1: addLabel('x<sub>1</sub>', x1Tip, { fontSize: '14px', color: '#16c900', bold: true }),
  y1: addLabel('y<sub>1</sub>', y1Tip, { fontSize: '14px', color: '#16c900', bold: true }),
  z1: addLabel('z<sub>1</sub>', z1Tip, { fontSize: '14px', color: '#16c900', bold: true }),

  camera2: setSerif(addLabel('Camera 2', new THREE.Vector3(), { fontSize: '34px', color: '#000' })),
  image2: addLabel('image plane 2', new THREE.Vector3(), { fontSize: '13px', color: '#111', background: 'rgba(255,255,255,0.78)' }),
  p2: setSerif(addLabel('p<sub>2</sub> ?', new THREE.Vector3(), { fontSize: '44px', color: '#000' }), 'bold'),
  epipolar: addLabel('epipolar line on image plane 2', new THREE.Vector3(), { fontSize: '13px', color: '#d40000', background: 'rgba(255,255,255,0.82)' }),
  rayProjection: addLabel('projection of Camera 1 ray', new THREE.Vector3(), { fontSize: '12px', color: '#d40000', background: 'rgba(255,255,255,0.78)' }),
  e2: addLabel('e<sub>2</sub> = projection of Camera 1', new THREE.Vector3(), { fontSize: '12px', color: '#000', bold: true, background: 'rgba(255,255,255,0.78)' }),
  p1to2: addLabel('&pi;<sub>2</sub>(p<sub>1</sub>)', new THREE.Vector3(), { fontSize: '12px', color: '#008c8c', bold: true, background: 'rgba(255,255,255,0.78)' }),
  pointP2: addLabel('projection of P', new THREE.Vector3(), { fontSize: '12px', color: '#158000', background: 'rgba(255,255,255,0.78)' }),
  x2: addLabel('x<sub>2</sub>', new THREE.Vector3(), { fontSize: '14px', color: '#1d63e8', bold: true }),
  y2: addLabel('y<sub>2</sub>', new THREE.Vector3(), { fontSize: '14px', color: '#1d63e8', bold: true }),
  z2: addLabel('z<sub>2</sub>', new THREE.Vector3(), { fontSize: '14px', color: '#1d63e8', bold: true }),
  axes2: addLabel('coordinate axes 2', new THREE.Vector3(), { fontSize: '12px', color: '#1d63e8', background: 'rgba(255,255,255,0.75)' }),
  RT: setSerif(addLabel('R,T', new THREE.Vector3(), { fontSize: '54px', color: '#18c900' }), 'bold'),
  T: addLabel('T', new THREE.Vector3(), { fontSize: '20px', color: '#18c900', bold: true, background: 'rgba(255,255,255,0.62)' })
};

const demoSteps = [
  {
    title: 'Initial Setup',
    narration: 'Here, you see Camera 1 and Camera 2 with their respective image planes. The red line is the ray from Camera 1; its projection is the red epipolar line on image plane 2.',
    rotationCamera2: 0,
    translationCamera2: 0
  },
  {
    title: 'Rotate Camera 2',
    narration: 'As we rotate Camera 2, the image plane changes orientation, so the red epipolar line shifts on image plane 2.',
    rotationCamera2: 45,
    translationCamera2: 0
  },
  {
    title: 'Translate Camera 2',
    narration: 'Translating Camera 2 changes the baseline T. The epipole and the red epipolar line move, changing the candidate locations for p\u2082.',
    rotationCamera2: 45,
    translationCamera2: 5
  }
];

function updateScene() {
  disposeGroup(dynamicGroup);

  const C2 = camera2Center();
  const n2 = camera2Normal();
  const b2 = makeBasisFromNormal(n2);
  const plane2Center = C2.clone().addScaledVector(n2, 2.30)
    .addScaledVector(b2.u, -0.05)
    .addScaledVector(b2.v, 0.04);

  const plane2 = addPlaneOutline(dynamicGroup, plane2Center, n2, 3.10, 3.64, BLACK, 0.029);
  addCamera(dynamicGroup, C2, plane2.corners, n2, -1);

  const e2 = projectFromCameraToPlane(C2, C1, plane2Center, n2);
  const p2 = projectFromCameraToPlane(C2, P, plane2Center, n2);
  const p1OnPlane2 = projectFromCameraToPlane(C2, p1, plane2Center, n2);
  const [lineA, lineB] = clipLineToPlaneRect(e2, p2, plane2Center, plane2.u, plane2.v, plane2.width, plane2.height);

  addDashedSegment(dynamicGroup, C1, C2, BLACK, 0.018, 0.26, 0.18);
  addDashedSegment(dynamicGroup, C2, P, BLACK, 0.018, 0.25, 0.17);
  addDashedSegment(dynamicGroup, C1, e2, BLACK, 0.016, 0.23, 0.17);
  addDashedSegment(dynamicGroup, P, p2, BLACK, 0.016, 0.23, 0.16);
  addDashedSegment(dynamicGroup, p1, p1OnPlane2, BLACK, 0.016, 0.23, 0.16);

  addCylinderBetween(dynamicGroup, lineA, lineB, 0.048, RED, 1, 24);

  const epipolarPlaneGeom = new THREE.BufferGeometry().setFromPoints([C1, C2, P]);
  epipolarPlaneGeom.setIndex([0, 1, 2]);
  const epipolarPlane = new THREE.Mesh(
    epipolarPlaneGeom,
    new THREE.MeshBasicMaterial({
      color: MAGENTA,
      transparent: true,
      opacity: 0.10,
      side: THREE.DoubleSide,
      depthWrite: false
    })
  );
  dynamicGroup.add(epipolarPlane);

  addPoint(dynamicGroup, e2, RED, 0.112);
  addPoint(dynamicGroup, p2, GREEN, 0.112);
  addPoint(dynamicGroup, p1OnPlane2, CYAN, 0.098);

  const origin2 = plane2Center.clone().addScaledVector(n2, 0.10);
  const x2Tip = addArrow(dynamicGroup, origin2, plane2.u.clone().multiplyScalar(-1), 1.12, BLUE, 0.019, 0.92);
  const y2Tip = addArrow(dynamicGroup, origin2, plane2.v, 1.16, BLUE, 0.019, 0.92);
  const z2Tip = addArrow(dynamicGroup, origin2, n2, 0.94, BLUE, 0.019, 0.92);

  const tStart = C1.clone().add(new THREE.Vector3(0.05, -0.58, 0.62));
  const tEnd = C2.clone().add(new THREE.Vector3(-0.05, -0.58, 0.62));
  addArrow(dynamicGroup, tStart, new THREE.Vector3().subVectors(tEnd, tStart), tStart.distanceTo(tEnd), GREEN, 0.026, 1.08);

  const curveStart = C1.clone().add(new THREE.Vector3(1.05, -1.05, 0.92));
  const curveEnd = C2.clone().add(new THREE.Vector3(-1.10, -1.05, 0.92));
  const curveControl = new THREE.Vector3((curveStart.x + curveEnd.x) * 0.5, -3.42, 1.22);
  addCurvedArrow(dynamicGroup, curveStart, curveControl, curveEnd, GREEN, 0.032);

  labels.camera2.pos.copy(C2).add(new THREE.Vector3(0.76, -0.45, -0.02));
  labels.image2.pos.copy(plane2.corners[2]).add(new THREE.Vector3(0.06, 0.23, 0.02));
  labels.p2.pos.copy(p2).add(new THREE.Vector3(-0.33, 0.02, 0.04));
  labels.epipolar.pos.copy(lineA).lerp(lineB, 0.72).add(new THREE.Vector3(0.04, 0.19, 0.04));
  labels.rayProjection.pos.copy(lineA).lerp(lineB, 0.42).add(new THREE.Vector3(0.09, -0.16, 0.04));
  labels.e2.pos.copy(e2).add(new THREE.Vector3(0.20, -0.16, 0.02));
  labels.p1to2.pos.copy(p1OnPlane2).add(new THREE.Vector3(0.20, 0.15, 0.02));
  labels.pointP2.pos.copy(p2).add(new THREE.Vector3(0.18, 0.18, 0.02));
  labels.x2.pos.copy(x2Tip);
  labels.y2.pos.copy(y2Tip);
  labels.z2.pos.copy(z2Tip);
  labels.axes2.pos.copy(origin2).add(new THREE.Vector3(0.54, 0.16, 0.02));
  labels.T.pos.copy(tStart).lerp(tEnd, 0.5).add(new THREE.Vector3(0, 0.22, 0.02));
  labels.RT.pos.copy(curveControl).add(new THREE.Vector3(0, -0.20, 0));

  document.getElementById('rotationCamera2Value').textContent = `${Math.round(state.rotationCamera2)}\u00b0`;
  document.getElementById('translationCamera2Value').textContent = state.translationCamera2.toFixed(1);
  document.getElementById('rotationCamera2').value = state.rotationCamera2;
  document.getElementById('translationCamera2').value = state.translationCamera2;

  for (let i = 0; i < 3; i++) {
    document.getElementById(`step${i}`).classList.toggle('active', state.activeStep === i);
  }
  const step = demoSteps[state.activeStep];
  document.getElementById('stepNarration').textContent = step ? step.narration : 'Adjust either slider independently to explore how camera pose changes the epipolar constraint.';
}

const rotationInput = document.getElementById('rotationCamera2');
const translationInput = document.getElementById('translationCamera2');

rotationInput.addEventListener('input', () => {
  state.tween = null;
  state.activeStep = -1;
  state.rotationCamera2 = Number(rotationInput.value);
  updateScene();
});

translationInput.addEventListener('input', () => {
  state.tween = null;
  state.activeStep = -1;
  state.translationCamera2 = Number(translationInput.value);
  updateScene();
});

function goToStep(i) {
  const target = demoSteps[i];
  if (!target) return;

  state.activeStep = i;
  state.tween = {
    startTime: performance.now(),
    duration: 1000,
    fromRotation: state.rotationCamera2,
    fromTranslation: state.translationCamera2,
    toRotation: target.rotationCamera2,
    toTranslation: target.translationCamera2
  };

  function tick(now) {
    if (!state.tween) return;
    const t = Math.min((now - state.tween.startTime) / state.tween.duration, 1);
    const eased = t < 0.5 ? 2 * t * t : 1 - Math.pow(-2 * t + 2, 2) / 2;
    state.rotationCamera2 = THREE.MathUtils.lerp(state.tween.fromRotation, state.tween.toRotation, eased);
    state.translationCamera2 = THREE.MathUtils.lerp(state.tween.fromTranslation, state.tween.toTranslation, eased);
    updateScene();

    if (t < 1) {
      requestAnimationFrame(tick);
    } else {
      state.rotationCamera2 = state.tween.toRotation;
      state.translationCamera2 = state.tween.toTranslation;
      state.tween = null;
      updateScene();
    }
  }

  requestAnimationFrame(tick);
}

document.getElementById('step0').addEventListener('click', () => goToStep(0));
document.getElementById('step1').addEventListener('click', () => goToStep(1));
document.getElementById('step2').addEventListener('click', () => goToStep(2));
window.goToStep = goToStep;

camera.position.set(0.38, 3.05, 9.65);
controls.target.set(0.02, -0.44, 0.24);
camera.zoom = 0.52;
camera.lookAt(controls.target);
camera.updateProjectionMatrix();
controls.update();
HOME_POS.copy(camera.position);
HOME_TARGET.copy(controls.target);
HOME_ZOOM = camera.zoom;

updateScene();
// @FIGURE_CODE_END

