function makeNoiseTexture(seedShift = 0) {
  const c = document.createElement('canvas');
  c.width = 96;
  c.height = 256;
  const ctx = c.getContext('2d');
  const img = ctx.createImageData(c.width, c.height);
  let s = 12345 + seedShift;
  function rnd() {
    s = (1664525 * s + 1013904223) >>> 0;
    return s / 4294967296;
  }
  for (let i = 0; i < img.data.length; i += 4) {
    const base = 120 + Math.floor(rnd() * 110);
    img.data[i] = Math.max(0, Math.min(255, base + Math.floor((rnd() - 0.5) * 90)));
    img.data[i + 1] = Math.max(0, Math.min(255, base + Math.floor((rnd() - 0.5) * 80)));
    img.data[i + 2] = Math.max(0, Math.min(255, base + Math.floor((rnd() - 0.5) * 95)));
    img.data[i + 3] = 255;
  }
  ctx.putImageData(img, 0, 0);
  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  return tex;
}

function boxMaterials(spec) {
  if (spec.image) {
    const texture = makeNoiseTexture(spec.x > 0 ? 50 : 0);
    const side = new THREE.MeshBasicMaterial({ color: 0xb8b8b8, transparent: true, opacity: 1 });
    const front = new THREE.MeshBasicMaterial({ map: texture, transparent: true, opacity: 1 });
    return [side.clone(), side.clone(), side.clone(), side.clone(), front, side.clone()];
  }
  return [
    new THREE.MeshBasicMaterial({ color: COPPER_SIDE, transparent: true, opacity: 1 }),
    new THREE.MeshBasicMaterial({ color: COPPER_SIDE, transparent: true, opacity: 1 }),
    new THREE.MeshBasicMaterial({ color: COPPER_TOP, transparent: true, opacity: 1 }),
    new THREE.MeshBasicMaterial({ color: COPPER_FRONT, transparent: true, opacity: 1 }),
    new THREE.MeshBasicMaterial({ color: COPPER_FRONT, transparent: true, opacity: 1 }),
    new THREE.MeshBasicMaterial({ color: COPPER_SIDE, transparent: true, opacity: 1 })
  ];
}

