function makeBlock(name, spec) {
  const group = new THREE.Group();
  group.name = name;
  const geom = new THREE.BoxGeometry(spec.w, spec.h, spec.d);
  const mats = boxMaterials(spec);
  const mesh = new THREE.Mesh(geom, mats);
  mesh.position.set(spec.x, spec.h / 2, spec.d / 2);
  const edgeGeom = new THREE.EdgesGeometry(geom);
  const edge = new THREE.LineSegments(edgeGeom, new THREE.LineBasicMaterial({ color: EDGE, transparent: true, opacity: 1 }));
  edge.position.copy(mesh.position);
  group.add(mesh, edge);
  scene.add(group);
  blocks[name] = { name, spec, group, mesh, edge, mats };
  if (spec.attention) {
    registerInteractive(group, {
      title: 'Self-attention at low resolution',
      tooltip: 'Click to show 16×16 token attention',
      body: 'At 16×16, every spatial token can attend to all other positions. A plain residual block mixes mostly through local convolutional neighborhoods.',
      onClick: () => showAttentionOverlay(name)
    });
  }
  return group;
}

