const skipArrows = {};
function makeSkip(key, fromName, toName, yTop, labelX) {
  const from = blockSpecs[fromName];
  const to = blockSpecs[toName];
  const start = [from.x + from.w * 0.38, from.h + 0.10, 0.72];
  const elbow1 = [from.x + from.w * 0.85, yTop, 0.72];
  const elbow2 = [to.x - to.w * 0.85, yTop, 0.72];
  const end = [to.x - to.w * 0.35, to.h + 0.12, 0.72];
  const group = new THREE.Group();
  const line = new THREE.Line(
    new THREE.BufferGeometry().setFromPoints([start, elbow1, elbow2].map(p => new THREE.Vector3(p[0], p[1], p[2]))),
    new THREE.LineBasicMaterial({ color: SKIP, transparent: true, opacity: 0.82 })
  );
  group.add(line);
  const last = new THREE.Vector3(end[0], end[1], end[2]).sub(new THREE.Vector3(elbow2[0], elbow2[1], elbow2[2]));
  const head = new THREE.ArrowHelper(last.clone().normalize(), new THREE.Vector3(elbow2[0], elbow2[1], elbow2[2]), last.length(), SKIP, 0.18, 0.12);
  group.add(head);
  scene.add(group);
  skipArrows[key] = { group, line, head, labelPos: new THREE.Vector3(labelX, yTop + 0.14, 0.76) };
  return skipArrows[key];
}

