    const front = new THREE.MeshBasicMaterial({ map: texture, transparent: true, opacity: 1 });
    return [side.clone(), side.clone(), side.clone(), side.clone(), front, side.clone()];
  }
  return [
    new THREE.MeshBasicMaterial({ color: COPPER_SIDE, transparent: true, opacity: 1 }),
    new THREE.MeshBasicMaterial({ color: COPPER_SIDE, transparent: true, opacity: 1 }),
    new THREE.MeshBasicMaterial({ color: COPPER_TOP, transparent: true, opacity: 1 }),
