    const v = Math.sin((t + i * 37) / 220);
    entry.div.innerHTML = `e(t)<br>${v >= 0 ? '+' : ''}${v.toFixed(2)}`;
    entry.div.style.color = `rgb(${Math.round(60 + 60 * n)}, ${Math.round(100 + 45 * (1 - n))}, ${Math.round(125 + 70 * n)})`;
  });
  injectionArrows.forEach((a, i) => {
    const bright = 0.55 + 0.40 * (0.5 + 0.5 * Math.sin(t / 130 + i));
    arrowSetOpacity(a, bright, (blockSpecs[a.userData.block]?.attention ? TIME_LIGHT : TIME));
