function disposeGroup(group) {
  group.traverse(obj => {
    if (obj.geometry) obj.geometry.dispose?.();
    if (obj.material) {
      if (Array.isArray(obj.material)) obj.material.forEach(m => m.dispose?.());
      else obj.material.dispose?.();
    }
  });
  group.clear();
}

function makeBasisFromNormal(n) {
  let u = new THREE.Vector3().crossVectors(worldUp, n);
  if (u.lengthSq() < 1e-7) u = new THREE.Vector3(1, 0, 0).cross(n);
  u.normalize();
  const v = new THREE.Vector3().crossVectors(n, u).normalize();
  return { u, v };
}

function addCylinderBetween(parent, a, b, radius, color, opacity = 1, radial = 18) {
  const dir = new THREE.Vector3().subVectors(b, a);
  const len = dir.length();
  if (len < 1e-6) return null;
  const geom = new THREE.CylinderGeometry(radius, radius, len, radial);
  const mat = new THREE.MeshBasicMaterial({
    color,
    transparent: opacity < 1,
    opacity,
    depthWrite: opacity >= 0.98
  });
  const mesh = new THREE.Mesh(geom, mat);
  mesh.position.copy(a).add(b).multiplyScalar(0.5);
  mesh.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.normalize());
  parent.add(mesh);
  return mesh;
}

function addConeAt(parent, tip, dir, radius, height, color) {
  const d0 = dir.clone().normalize();
  const geom = new THREE.ConeGeometry(radius, height, 28);
  const mat = new THREE.MeshBasicMaterial({ color });
  const cone = new THREE.Mesh(geom, mat);
  cone.position.copy(tip).addScaledVector(d0, -height / 2);
  cone.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), d0);
  parent.add(cone);
  return cone;
}

function addArrow(parent, origin, dir, length, color, radius = 0.022, headScale = 1) {
  const d0 = dir.clone().normalize();
  const headH = Math.min(0.38 * headScale, Math.max(0.15, length * 0.26));
  const shaftEnd = origin.clone().addScaledVector(d0, Math.max(length - headH * 0.72, 0.01));
  const tip = origin.clone().addScaledVector(d0, length);
  addCylinderBetween(parent, origin, shaftEnd, radius, color, 1, 16);
  addConeAt(parent, tip, d0, radius * 5.7 * headScale, headH, color);
  return tip;
}

function addDashedSegment(parent, a, b, color = BLACK, radius = 0.018, dash = 0.25, gap = 0.17) {
  const delta = new THREE.Vector3().subVectors(b, a);
  const len = delta.length();
  if (len < 1e-6) return;
  const dir = delta.clone().normalize();
  for (let t = 0; t < len; t += dash + gap) {
    const t2 = Math.min(t + dash, len);
    addCylinderBetween(
      parent,
      a.clone().addScaledVector(dir, t),
      a.clone().addScaledVector(dir, t2),
      radius,
      color,
      1,
      12
    );
  }
}

function addThickPolyline(parent, points, color = BLACK, radius = 0.026, closed = false) {
  const n = closed ? points.length : points.length - 1;
  for (let i = 0; i < n; i++) {
    addCylinderBetween(parent, points[i], points[(i + 1) % points.length], radius, color, 1, 16);
  }
}

function addPlanePatch(parent, corners, color = WHITE, opacity = 0.16) {
  const geom = new THREE.BufferGeometry().setFromPoints([corners[0], corners[1], corners[2], corners[0], corners[2], corners[3]]);
  geom.setIndex([0, 1, 2, 3, 4, 5]);
  const mat = new THREE.MeshBasicMaterial({
    color,
    transparent: true,
    opacity,
    side: THREE.DoubleSide,
    depthWrite: false
  });
  const mesh = new THREE.Mesh(geom, mat);
  parent.add(mesh);
  return mesh;
}

function addPlaneOutline(parent, center, normal, width, height, color = BLACK, radius = 0.028) {
  const { u, v } = makeBasisFromNormal(normal);
  const corners = [
    center.clone().addScaledVector(u, -width / 2).addScaledVector(v, -height / 2),
    center.clone().addScaledVector(u, width / 2).addScaledVector(v, -height / 2),
    center.clone().addScaledVector(u, width / 2).addScaledVector(v, height / 2),
    center.clone().addScaledVector(u, -width / 2).addScaledVector(v, height / 2)
  ];
  addPlanePatch(parent, corners, WHITE, 0.10);
  addThickPolyline(parent, corners, color, radius, true);
  return { corners, u, v, center, normal: normal.clone(), width, height };
}

function addCamera(parent, center, planeCorners, facingDir, labelSide = 1) {
  const body = new THREE.Mesh(
    new THREE.SphereGeometry(0.22, 40, 20),
    new THREE.MeshBasicMaterial({ color: BLACK })
  );
  body.position.copy(center);
  parent.add(body);

  const aperture = new THREE.Mesh(
    new THREE.SphereGeometry(0.12, 32, 16),
    new THREE.MeshBasicMaterial({ color: 0x000000 })
  );
  aperture.position.copy(center).addScaledVector(facingDir.clone().normalize(), 0.035);
  parent.add(aperture);

  for (const c of planeCorners) addCylinderBetween(parent, center, c, 0.021, BLACK, 1, 14);

  const base = center.clone().add(new THREE.Vector3(0.34 * labelSide, 0.00, -0.06));
  addCylinderBetween(parent, center, base, 0.03, BLACK, 1, 14);
}

function addPoint(parent, pos, fillColor, radius = 0.115, outlineColor = BLACK, outlineScale = 1.38) {
  const halo = new THREE.Mesh(
    new THREE.SphereGeometry(radius * outlineScale, 36, 18),
    new THREE.MeshBasicMaterial({ color: outlineColor })
  );
  halo.position.copy(pos);
  parent.add(halo);

  const dot = new THREE.Mesh(
    new THREE.SphereGeometry(radius, 36, 18),
    new THREE.MeshBasicMaterial({ color: fillColor })
  );
  dot.position.copy(pos);
  parent.add(dot);
  return dot;
}

function projectFromCameraToPlane(cameraCenter, objectPoint, planeCenter, planeNormal) {
  const ray = new THREE.Vector3().subVectors(objectPoint, cameraCenter);
  const denom = planeNormal.dot(ray);
  if (Math.abs(denom) < 1e-7) return planeCenter.clone();
  const t = planeNormal.dot(new THREE.Vector3().subVectors(planeCenter, cameraCenter)) / denom;
  return cameraCenter.clone().addScaledVector(ray, t);
}

function clipLineToPlaneRect(a, b, center, u, v, width, height) {
  const ap = new THREE.Vector3().subVectors(a, center);
  const bp = new THREE.Vector3().subVectors(b, center);
  const ax = ap.dot(u), ay = ap.dot(v);
  const bx = bp.dot(u), by = bp.dot(v);
  const dx = bx - ax, dy = by - ay;
  const hw = width / 2, hh = height / 2;
  const ts = [];

  function addT(t) {
    if (!Number.isFinite(t)) return;
    const x = ax + dx * t;
    const y = ay + dy * t;
    if (x >= -hw - 1e-5 && x <= hw + 1e-5 && y >= -hh - 1e-5 && y <= hh + 1e-5) ts.push(t);
  }

  if (Math.abs(dx) > 1e-9) {
    addT((-hw - ax) / dx);
    addT((hw - ax) / dx);
  }
  if (Math.abs(dy) > 1e-9) {
    addT((-hh - ay) / dy);
    addT((hh - ay) / dy);
  }

  ts.sort((m, n) => m - n);
  const unique = ts.filter((t, i) => i === 0 || Math.abs(t - ts[i - 1]) > 1e-4);
  if (unique.length >= 2) return [a.clone().lerp(b, unique[0]), a.clone().lerp(b, unique[unique.length - 1])];

  const localDir = new THREE.Vector2(dx, dy);
  if (localDir.lengthSq() < 1e-9) {
    return [
      center.clone().addScaledVector(u, -hw),
      center.clone().addScaledVector(u, hw)
    ];
  }
  localDir.normalize();
  const local = new THREE.Vector2(ax, ay);
  const tClosest = -local.dot(localDir);
  const cx = ax + localDir.x * tClosest;
  const cy = ay + localDir.y * tClosest;
  const span = Math.sqrt(hw * hw + hh * hh);
  return [
    center.clone().addScaledVector(u, cx - localDir.x * span).addScaledVector(v, cy - localDir.y * span),
    center.clone().addScaledVector(u, cx + localDir.x * span).addScaledVector(v, cy + localDir.y * span)
  ];
}

function addCurvedArrow(parent, start, control, end, color, radius = 0.032) {
  const curve = new THREE.QuadraticBezierCurve3(start, control, end);
  const tube = new THREE.Mesh(
    new THREE.TubeGeometry(curve, 96, radius, 12, false),
    new THREE.MeshBasicMaterial({ color })
  );
  parent.add(tube);
  addConeAt(parent, end, curve.getTangent(1).normalize(), 0.22, 0.44, color);
}

function setSerif(labelEntry, weight = 'normal') {
  labelEntry.div.style.fontFamily = 'Georgia, Times New Roman, serif';
  labelEntry.div.style.fontWeight = weight;
  return labelEntry;
}

const plane1Normal = rayDir1.clone();
const basis1 = makeBasisFromNormal(plane1Normal);
const p1 = C1.clone().addScaledVector(rayDir1, 2.78);
const plane1Center = p1.clone()
  .addScaledVector(basis1.u, -0.60)
  .addScaledVector(basis1.v, 0.06);

const plane1 = addPlaneOutline(fixedGroup, plane1Center, plane1Normal, 3.05, 3.62, BLACK, 0.029);
addCamera(fixedGroup, C1, plane1.corners, plane1Normal, 1);

const rayEnd = C1.clone().addScaledVector(rayDir1, 8.75);
addCylinderBetween(fixedGroup, C1, rayEnd, 0.052, RED, 1, 24);
addPoint(fixedGroup, p1, RED, 0.115);
addPoint(fixedGroup, P, CYAN, 0.12);

const axisOrigin1 = plane1Center.clone().addScaledVector(plane1Normal, 0.10);
const x1Tip = addArrow(fixedGroup, axisOrigin1, plane1.u.clone().multiplyScalar(-1), 1.13, GREEN, 0.019, 0.92);
const y1Tip = addArrow(fixedGroup, axisOrigin1, plane1.v, 1.16, GREEN, 0.019, 0.92);
const z1Tip = addArrow(fixedGroup, axisOrigin1, plane1Normal, 0.93, GREEN, 0.019, 0.92);

function camera2Center() {
  return new THREE.Vector3(
    4.20 + state.translationCamera2 * 0.18,
    -1.62,
    0.08 + state.translationCamera2 * 0.052
  );
}

function camera2Normal() {
  const base = new THREE.Vector3(-1.66, 0.78, 0.08).normalize();
  return base.applyAxisAngle(worldUp, THREE.MathUtils.degToRad(state.rotationCamera2)).normalize();
}

const labels = {
