function setObjectOpacity(obj, opacity) {
  obj.traverse(o => {
    if (o.material) {
      const arr = Array.isArray(o.material) ? o.material : [o.material];
      arr.forEach(m => {
        m.transparent = true;
        m.opacity = opacity;
        m.needsUpdate = true;
      });
    }
  });
}

function setObjectColor(obj, color) {
  obj.traverse(o => {
    if (o.isMesh && o.material && !o.material.map) {
      const arr = Array.isArray(o.material) ? o.material : [o.material];
      arr.forEach(m => { if (m.color) m.color.setHex(color); });
    }
  });
}

function makeArrow(start, end, color = 0x222222, headLength = 0.16, headWidth = 0.10, opacity = 1) {
  const s = new THREE.Vector3(start[0], start[1], start[2] ?? 0.65);
  const e = new THREE.Vector3(end[0], end[1], end[2] ?? 0.65);
  const dir = e.clone().sub(s);
  const len = Math.max(dir.length(), 1e-6);
  const arrow = new THREE.ArrowHelper(dir.clone().normalize(), s, len, color, headLength, headWidth);
  arrow.traverse(o => {
    if (o.material) {
      o.material.transparent = true;
      o.material.opacity = opacity;
      if (o.material.color) o.material.color.setHex(color);
    }
  });
  scene.add(arrow);
  return arrow;
}

function makeLine(points, color = 0x222222, opacity = 1) {
  const pts = points.map(p => new THREE.Vector3(p[0], p[1], p[2] ?? 0.65));
  const line = new THREE.Line(
    new THREE.BufferGeometry().setFromPoints(pts),
    new THREE.LineBasicMaterial({ color, transparent: true, opacity })
  );
  scene.add(line);
  return line;
}

function makeTextPlane(text, pos, opts = {}) {
  const fontSize = opts.fontSize || 44;
  const family = opts.family || 'Georgia, Times New Roman, serif';
  const italic = opts.italic ? 'italic ' : '';
  const weight = opts.bold ? 'bold ' : '';
  const pad = 20;
  const c = document.createElement('canvas');
  const ctx = c.getContext('2d');
  ctx.font = `${italic}${weight}${fontSize}px ${family}`;
  const metrics = ctx.measureText(text);
  c.width = Math.ceil(metrics.width + pad * 2);
  c.height = Math.ceil(fontSize * 1.55 + pad);
  ctx.font = `${italic}${weight}${fontSize}px ${family}`;
  ctx.textBaseline = 'middle';
  ctx.textAlign = 'center';
  ctx.fillStyle = opts.color || '#111';
  ctx.clearRect(0, 0, c.width, c.height);
  ctx.fillText(text, c.width / 2, c.height / 2);
  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  const h = opts.height || 0.24;
  const w = h * c.width / c.height;
  const mesh = new THREE.Mesh(
    new THREE.PlaneGeometry(w, h),
    new THREE.MeshBasicMaterial({ map: tex, transparent: true, side: THREE.DoubleSide })
  );
  mesh.position.set(pos[0], pos[1], pos[2] ?? 0.86);
  mesh.rotation.z = THREE.MathUtils.degToRad(opts.angleDeg || 0);
  (opts.parent || scene).add(mesh);
  return mesh;
}

