function buildAttentionOverlay() {
  const panel = new THREE.Mesh(
    new THREE.PlaneGeometry(4.45, 2.55),
    new THREE.MeshBasicMaterial({ color: 0xffffff, transparent: true, opacity: 0.97, side: THREE.DoubleSide })
  );
  panel.position.set(0.72, 2.18, 1.05);
  attentionOverlay.add(panel);
  addPanelBorder(attentionOverlay, 0.72, 2.18, 4.45, 2.55, 1.075);
  makeTextPlane('Self-attention: one 16×16 query sees all tokens', [0.42, 3.23, 1.13], { parent: attentionOverlay, fontSize: 46, height: 0.20, color: '#7f3b22' });

  const x0 = -1.18, y0 = 1.18, size = 1.55, step = size / 16;
  const lines = [];
  for (let i = 0; i <= 16; i++) {
    lines.push(new THREE.Vector3(x0 + i * step, y0, 1.10), new THREE.Vector3(x0 + i * step, y0 + size, 1.10));
    lines.push(new THREE.Vector3(x0, y0 + i * step, 1.10), new THREE.Vector3(x0 + size, y0 + i * step, 1.10));
  }
  attentionOverlay.add(new THREE.LineSegments(new THREE.BufferGeometry().setFromPoints(lines), new THREE.LineBasicMaterial({ color: TIME, transparent: true, opacity: 0.58 })));
  const qx = x0 + 7.5 * step, qy = y0 + 8.5 * step;
  const query = new THREE.Mesh(new THREE.PlaneGeometry(step * 1.25, step * 1.25), new THREE.MeshBasicMaterial({ color: 0xffd84a, transparent: true, opacity: 0.98, side: THREE.DoubleSide }));
  query.position.set(qx, qy, 1.13);
  attentionOverlay.add(query);
  const attnPts = [];
  for (let iy = 0; iy < 16; iy++) {
    for (let ix = 0; ix < 16; ix++) {
      attnPts.push(new THREE.Vector3(qx, qy, 1.118), new THREE.Vector3(x0 + (ix + 0.5) * step, y0 + (iy + 0.5) * step, 1.118));
    }
  }
  const fan = new THREE.LineSegments(new THREE.BufferGeometry().setFromPoints(attnPts), new THREE.LineBasicMaterial({ color: SKIP, transparent: true, opacity: 0.12 }));
  fan.userData.attentionFan = true;
  attentionOverlay.add(fan);

  const miniX = 1.25, miniY = 1.38, miniSize = 0.82, miniStep = miniSize / 5;
  const miniPanel = new THREE.Mesh(new THREE.PlaneGeometry(1.35, 1.38), new THREE.MeshBasicMaterial({ color: 0xf8f8f8, transparent: true, opacity: 1, side: THREE.DoubleSide }));
  miniPanel.position.set(1.88, 1.82, 1.09);
  attentionOverlay.add(miniPanel);
  addPanelBorder(attentionOverlay, 1.88, 1.82, 1.35, 1.38, 1.115, 0x777777);
  const miniLines = [];
  for (let i = 0; i <= 5; i++) {
    miniLines.push(new THREE.Vector3(miniX + i * miniStep, miniY, 1.12), new THREE.Vector3(miniX + i * miniStep, miniY + miniSize, 1.12));
    miniLines.push(new THREE.Vector3(miniX, miniY + i * miniStep, 1.12), new THREE.Vector3(miniX + miniSize, miniY + i * miniStep, 1.12));
  }
  attentionOverlay.add(new THREE.LineSegments(new THREE.BufferGeometry().setFromPoints(miniLines), new THREE.LineBasicMaterial({ color: 0x444444, transparent: true, opacity: 0.48 })));
  for (let iy = 1; iy <= 3; iy++) for (let ix = 1; ix <= 3; ix++) {
    const cell = new THREE.Mesh(new THREE.PlaneGeometry(miniStep * 0.92, miniStep * 0.92), new THREE.MeshBasicMaterial({ color: ix === 2 && iy === 2 ? 0xffd84a : TIME_LIGHT, transparent: true, opacity: 0.86, side: THREE.DoubleSide }));
    cell.position.set(miniX + (ix + 0.5) * miniStep, miniY + (iy + 0.5) * miniStep, 1.13);
    attentionOverlay.add(cell);
  }
  makeTextPlane('plain residual block', [1.89, 2.52, 1.14], { parent: attentionOverlay, fontSize: 40, height: 0.17, color: '#333' });
  makeTextPlane('local neighbors only', [1.88, 1.15, 1.14], { parent: attentionOverlay, fontSize: 36, height: 0.15, color: TIME });
}
