  attentionOverlay.visible = false;
  hidePopup();
  document.getElementById('statusText').textContent = 'Attention overlay hidden. Click a 16×16 block to show it again.';
});

setCameraView({ projection: 'oblique', obliqueAngleDeg: 45, depthScale: 0.5, rollDeg: 0, heightFraction: 0.72 });

addLabel('t', new THREE.Vector3(-7.72, -0.60, 0.82), { color: '#4f6f80', fontSize: '24px' });
addLabel('time embedding', new THREE.Vector3(-6.45, -0.86, 0.82), { color: '#4f6f80', fontSize: '28px' });
for (const key of Object.keys(skipArrows)) {
  addLabel('Concatenate', skipArrows[key].labelPos, { color: SKIP_TEXT, fontSize: key === 'dec256Concat' ? '31px' : '29px' });
}

const stages = [
  'input', 'enc256', 'enc128', 'enc64', 'enc32', 'enc16Attention', 'bottleneck8',
  'dec16Concat', 'dec32Concat', 'dec64Concat', 'dec128Concat', 'dec256Concat', 'output'
];

const stageBlocks = {
  input: ['input'],
  enc256: ['enc256a', 'enc256b'],
  enc128: ['enc128'],
  enc64: ['enc64'],
  enc32: ['enc32'],
  enc16Attention: ['enc16'],
  bottleneck8: ['bottleneck8', 'dec8'],
  dec16Concat: ['dec16'],
  dec32Concat: ['dec32'],
  dec64Concat: ['dec64'],
  dec128Concat: ['dec128'],
  dec256Concat: ['dec256a', 'dec256b'],
  output: ['output']
};

const stageSkip = {
  dec16Concat: 'dec16Concat',
  dec32Concat: 'dec32Concat',
  dec64Concat: 'dec64Concat',
  dec128Concat: 'dec128Concat',
  dec256Concat: 'dec256Concat'
};

let currentStage = 'input';
let pulse = 0;

function arrowSetOpacity(arrow, opacity, color) {
  arrow.traverse(o => {
    if (o.material) {
      o.material.transparent = true;
      o.material.opacity = opacity;
      if (o.material.color && color !== undefined) o.material.color.setHex(color);
    }
  });
}

function resetBlockColor(name) {
  const b = blocks[name];
  if (b.spec.image) return;
  b.mats.forEach((m, i) => {
    if (i === 0 || i === 1 || i === 5) m.color.setHex(COPPER_SIDE);
    else if (i === 2) m.color.setHex(COPPER_TOP);
    else m.color.setHex(COPPER_FRONT);
  });
}

function updatePassStage(stage) {
  currentStage = stage;
  document.getElementById('passStage').value = stage;
  const active = new Set(stageBlocks[stage] || []);
  for (const name of blockOrder) {
    resetBlockColor(name);
    setObjectOpacity(blocks[name].group, active.has(name) ? 1 : DIMMED_OPACITY);
    if (active.has(name) && !blocks[name].spec.image) setObjectColor(blocks[name].mesh, ACTIVE);
  }
  for (const arrow of pathArrows) {
    const on = arrow.userData.key === stage || (stage === 'enc256' && arrow.userData.key === 'input');
    arrow.userData.active = on;
    arrowSetOpacity(arrow, on ? 1 : 0.42, on ? 0x111111 : arrow.userData.baseColor);
  }
  for (const key of Object.keys(skipArrows)) {
    const sk = skipArrows[key];
    const on = stageSkip[stage] === key;
    sk.group.userData.active = on;
    sk.group.traverse(o => {
      if (o.material) {
        o.material.transparent = true;
        o.material.opacity = on ? 1 : 0.38;
        if (o.material.color) o.material.color.setHex(SKIP);
      }
    });
  }
  if (stage === 'enc16Attention') {
    document.getElementById('statusText').textContent = '16×16 self-attention block is highlighted. Click it to open the token grid.';
  } else if (stageSkip[stage]) {
    document.getElementById('statusText').textContent = 'A matching encoder feature map is concatenated into the decoder at this stage.';
  } else {
    document.getElementById('statusText').textContent = 'Follow the highlighted U-Net block and path arrow.';
  }
}

function updateTimestep(t) {
  const n = t / 1000;
  const vals = [
    Math.sin(t / 180),
    Math.cos(t / 180),
    Math.sin(t / 36),
    Math.cos(t / 36)
  ];
  document.getElementById('tReadout').textContent = `t = ${t}`;
  document.getElementById('embedReadout').textContent = `time embedding: [${vals.map(v => (v >= 0 ? '+' : '') + v.toFixed(2)).join(', ')}]`;
  injectionArrows.forEach((a, i) => {
    const bright = 0.62 + 0.33 * (0.5 + 0.5 * Math.sin(t / 130 + i * 0.7));
    const block = blockSpecs[a.userData.block];
    const col = block?.attention ? TIME_LIGHT : TIME;
    arrowSetOpacity(a, bright, col);
  });
  timeLine.material.opacity = 0.75 + 0.25 * n;
}

document.getElementById('passStage').addEventListener('change', e => updatePassStage(e.target.value));
document.getElementById('prevStage').addEventListener('click', () => {
  const i = stages.indexOf(currentStage);
  updatePassStage(stages[Math.max(0, i - 1)]);
});
document.getElementById('nextStage').addEventListener('click', () => {
  const i = stages.indexOf(currentStage);
  updatePassStage(stages[Math.min(stages.length - 1, i + 1)]);
});
document.getElementById('diffusionTimestep').addEventListener('input', e => updateTimestep(Number(e.target.value)));

const demoSteps = [
  {
    title: 'Noisy input and time condition',
    narration: 'The noisy 256×256×3 input enters from the left. The timestep node t produces a time embedding that will be injected into every residual block.',
    state: { passStage: 'input', diffusionTimestep: 500 }
  },
  {
    title: 'Encoder downsamples',
    narration: 'The encoder moves down the left side of the U: spatial size shrinks from 256×256 to lower resolutions while channel depth grows. The highlighted arrows show the active residual/downsampling path.',
    state: { passStage: 'enc64', diffusionTimestep: 500 }
  },
  {
    title: 'Low-resolution attention',
    narration: 'Near 16×16 and 8×8, the feature map is small enough for self-attention across all spatial positions. Clicking the highlighted block opens the attention overlay.',
    state: { passStage: 'enc16Attention', diffusionTimestep: 500 }
  },
  {
    title: 'Bottleneck',
    narration: 'At 8×8×512, the representation is spatially compact but channel-rich. This is the narrowest part of the U-Net.',
    state: { passStage: 'bottleneck8', diffusionTimestep: 500 }
  },
  {
    title: 'Decoder upsamples with skips',
    narration: 'As the decoder restores resolution, matching encoder features are concatenated into the decoder stream. The active skip arrow pulses when its concatenate operation is reached.',
    state: { passStage: 'dec64Concat', diffusionTimestep: 500 }
  },
  {
    title: 'Different diffusion time',
    narration: 'Moving t changes the numeric time embedding injected into every residual block, indicating that the same U-Net is conditioned differently at early versus late denoising steps.',
    state: { passStage: 'dec256Concat', diffusionTimestep: 900 }
  }
];

let currentStep = 0;
function goToStep(i) {
  currentStep = Math.max(0, Math.min(demoSteps.length - 1, i));
  const step = demoSteps[currentStep];
  document.getElementById('stepTitle').textContent = step.title;
  document.getElementById('stepNarration').textContent = step.narration;
  document.getElementById('diffusionTimestep').value = step.state.diffusionTimestep;
  updateTimestep(step.state.diffusionTimestep);
  updatePassStage(step.state.passStage);
  if (step.state.passStage !== 'enc16Attention') attentionOverlay.visible = false;
}
window.goToStep = goToStep;

document.getElementById('prevStep').addEventListener('click', () => goToStep(currentStep - 1));
document.getElementById('nextStep').addEventListener('click', () => goToStep(currentStep + 1));

function pulseLoop() {
  pulse += 0.055;
  const p = 0.60 + 0.40 * (0.5 + 0.5 * Math.sin(pulse));
  for (const arrow of pathArrows) {
    if (arrow.userData.active) arrowSetOpacity(arrow, p, arrow.userData.attention ? TIME_LIGHT : 0x000000);
  }
  for (const key of Object.keys(skipArrows)) {
    const sk = skipArrows[key];
    if (sk.group.userData.active) {
      sk.group.traverse(o => {
        if (o.material) {
          o.material.opacity = p;
          if (o.material.color) o.material.color.setHex(p > 0.78 ? 0xff9a69 : SKIP);
        }
      });
    }
  }
  if (attentionOverlay.visible) {
    attentionOverlay.traverse(child => {
      if (child.userData.attentionFan && child.material) {
        child.material.opacity = 0.08 + 0.08 * (0.5 + 0.5 * Math.sin(pulse * 1.4));
      }
    });
  }
  requestAnimationFrame(pulseLoop);
}
pulseLoop();

goToStep(0);
// @FIGURE_CODE_END

